class AwsauthcontextPlaceholder extends StatelessWidget {
  final dynamic data;
  const AwsauthcontextPlaceholder({super.key, this.data});

  @override
  Widget build(BuildContext context) {
    final ds = PrimeCareDesignSystem.of(context);
    return Container(
      padding: const EdgeInsets.all(24),
      decoration: BoxDecoration(
        color: ds.colors.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: ds.colors.borderSubtle),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(LucideIcons.component, color: ds.colors.primary.withValues(alpha: 0.5), size: 48),
          const SizedBox(height: 16),
          Text(
            'AWSAUTHCONTEXT',
            style: TextStyle(
              color: ds.colors.textPrimary,
              fontWeight: FontWeight.bold,
              letterSpacing: 1.2,
            ),
          ),
          const SizedBox(height: 8),
          Text(
            'This component is currently a placeholder for the aWSAuthContext intent.',
            textAlign: TextAlign.center,
            style: TextStyle(color: ds.colors.textSecondary, fontSize: 12),
          ),
        ],
      ),
    );
  }
}

